{"content":"export function golfScore(chars: number, keys: number, commands: number): number {
  if (keys === 0) return 0;
  const efficiency = chars / Math.max(1, keys);
  const bonus = Math.min(20, commands * 2);
  return Math.max(0, Math.min(100, Math.round(efficiency * 100 + bonus)));
}

export function golfVerdict(score: number): string {
  if (score >= 85) return 'surgical. the clerk nods.';
  if (score >= 65) return 'respectable. fewer hjkl next time.';
  if (score >= 40) return 'clumsy. the arrow keys saw everything.';
  return 'mashy. were you paddling upstream?';
}
","path":"web/src/lib/golf.ts"}

{"content":"export type AchDef = {id: string; title: string; desc: string};

export const ACHIEVEMENTS: AchDef[] = [
  {id: 'first-wq', title: 'First :wq', desc: 'Write and quit like you mean it.'},
  {id: 'colon-50', title: 'Colon dweller', desc: 'Run 50 ex commands.'},
  {id: 'x-1000', title: 'Patient eraser', desc: 'Delete 1000 chars with x.'},
  {id: 'no-mouse-100', title: 'Hands on home row', desc: '100 keystrokes without touching the mouse.'},
  {id: 'surgical', title: 'Surgical', desc: 'Confirm 10 substitutes with gc.'},
  {id: 'night-owl', title: 'Night owl', desc: ':w after midnight.'},
  {id: 'golf-80', title: 'Vim golf pro', desc: 'Score 80+ on a write.'},
];

export function checkAchievements(state: {
  unlocked: string[];
  colonCommands: number;
  xDeletes: number;
  mouseFreeStreak: number;
  gcConfirms: number;
  golfBest: number;
  hour: number;
}): string[] {
  const has = (id: string) => state.unlocked.includes(id);
  const fresh: string[] = [];
  if (!has('colon-50') && state.colonCommands >= 50) fresh.push('colon-50');
  if (!has('x-1000') && state.xDeletes >= 1000) fresh.push('x-1000');
  if (!has('no-mouse-100') && state.mouseFreeStreak >= 100) fresh.push('no-mouse-100');
  if (!has('surgical') && state.gcConfirms >= 10) fresh.push('surgical');
  if (!has('night-owl') && (state.hour === 0 || state.hour >= 22 || state.hour < 5)) fresh.push('night-owl');
  if (!has('golf-80') && state.golfBest >= 80) fresh.push('golf-80');
  return fresh;
}
","path":"web/src/lib/achievements.ts"}

{"content":"function escapeHtml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function inline(s: string): string {
  let out = escapeHtml(s);
  out = out.replace(/`([^`]+)`/g, '<code>$1</code>');
  out = out.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  out = out.replace(/(^|\W)\*([^*\n]+)\*/g, '$1<em>$2</em>');
  out = out.replace(/\[([^\]]+)\]\((https?:[^)\s]+)\)/g, '<a href="$2" rel="noreferrer">$1</a>');
  return out;
}

export function renderMarkdown(src: string): string {
  const lines = src.split('\n');
  const html: string[] = [];
  let inCode = false;
  let listOpen = false;
  for (const line of lines) {
    if (/^```/.test(line)) {
      html.push(inCode ? '</pre>' : '<pre>');
      inCode = !inCode;
      continue;
    }
    if (inCode) {
      html.push(escapeHtml(line));
      continue;
    }
    const h = /^(#{1,4})\s+(.*)$/.exec(line);
    if (h) {
      if (listOpen) {html.push('</ul>'); listOpen = false;}
      html.push(`<h${h[1].length} class="md-h">${inline(h[2])}</h${h[1].length}>`);
      continue;
    }
    if (/^\s*---\s*$/.test(line)) {
      if (listOpen) {html.push('</ul>'); listOpen = false;}
      html.push('<hr/>');
      continue;
    }
    if (/^&gt;/.test(escapeHtml(line)) || /^>/.test(line)) {
      if (listOpen) {html.push('</ul>'); listOpen = false;}
      html.push(`<blockquote>${inline(line.replace(/^>\s?/, ''))}</blockquote>`);
      continue;
    }
    const li = /^(\s*)[-*]\s+(.*)$/.exec(line);
    if (li) {
      if (!listOpen) {html.push('<ul>'); listOpen = true;}
      html.push(`<li>${inline(li[2])}</li>`);
      continue;
    }
    if (listOpen) {html.push('</ul>'); listOpen = false;}
    if (line.trim() === '') {
      html.push('<div class="md-gap"></div>');
      continue;
    }
    html.push(`<p>${inline(line)}</p>`);
  }
  if (listOpen) html.push('</ul>');
  if (inCode) html.push('</pre>');
  return html.join('\n');
}

export function docStats(text: string): {words: number; chars: number; minutes: number} {
  const words = text.trim() === '' ? 0 : text.trim().split(/\s+/).length;
  return {words, chars: text.length, minutes: Math.max(1, Math.ceil(words / 200))};
}
